import { Database } from "bun:sqlite";
import { drizzle } from "drizzle-orm/bun-sqlite";
import { migrate } from "drizzle-orm/bun-sqlite/migrator";
import { loadEnv } from "../config/env";

const env = loadEnv();

const dbDir = env.DATABASE_PATH.replace(/[/\\][^/\\]+$/, "");
if (dbDir && dbDir !== env.DATABASE_PATH) {
  await Bun.$`mkdir -p ${dbDir}`.quiet();
}

const sqlite = new Database(env.DATABASE_PATH);
const db = drizzle(sqlite);

migrate(db, { migrationsFolder: "./drizzle/migrations" });

console.log("Migrations applied successfully");

import { sql } from "drizzle-orm";
import { integer, sqliteTable, text } from "drizzle-orm/sqlite-core";

export const notes = sqliteTable("notes", {
  id: integer("id").primaryKey({ autoIncrement: true }),
  title: text("title").notNull().default(""),
  content: text("content").notNull().default(""),
  createdAt: text("created_at")
    .notNull()
    .default(sql`(datetime('now'))`),
  updatedAt: text("updated_at")
    .notNull()
    .default(sql`(datetime('now'))`),
});

export type Note = typeof notes.$inferSelect;
export type NewNote = typeof notes.$inferInsert;

import { cors } from "@elysiajs/cors";
import { staticPlugin } from "@elysiajs/static";
import { Elysia } from "elysia";
import { loadEnv } from "./config/env";
import { createDb } from "./db";
import { NotesRepository } from "./repositories/notes.repository";
import { createNotesRoutes } from "./routes/notes.routes";
import { NotesService } from "./services/notes.service";
import { successResponse } from "./types/api-response";

const env = loadEnv();
const db = createDb(env.DATABASE_PATH);
const notesService = new NotesService(new NotesRepository(db));

const app = new Elysia()
  .use(
    cors({
      origin: env.NODE_ENV === "production" ? false : env.CORS_ORIGIN,
      methods: ["GET", "POST", "PUT", "DELETE", "OPTIONS"],
    }),
  )
  .get("/health", () => successResponse({ status: "ok" }))
  .use(createNotesRoutes(notesService));

if (env.STATIC_DIR) {
  app.use(
    staticPlugin({
      assets: env.STATIC_DIR,
      prefix: "/",
    }),
  );

  app.get("/*", ({ request, set }) => {
    const url = new URL(request.url);
    if (url.pathname.startsWith("/notes") || url.pathname === "/health") {
      set.status = 404;
      return { success: false, message: "Not found" };
    }

    set.headers["content-type"] = "text/html; charset=utf-8";
    return Bun.file(`${env.STATIC_DIR}/index.html`);
  });
}

app.listen({
  hostname: "0.0.0.0",
  port: env.PORT,
});

console.log(
  `Simple Note API running at http://0.0.0.0:${env.PORT} (${env.NODE_ENV})`,
);

export type App = typeof app;

import { desc, eq, like, or } from "drizzle-orm";
import type { Db } from "../db";
import { notes } from "../db/schema";
import type {
  CreateNoteInput,
  Note,
  NoteListQuery,
  UpdateNoteInput,
} from "../types/note";

export class NotesRepository {
  constructor(private readonly db: Db) {}

  async findAll(query: NoteListQuery = {}): Promise<Note[]> {
    const search = query.search?.trim();

    const rows = search
      ? await this.db
          .select()
          .from(notes)
          .where(
            or(
              like(notes.title, `%${search}%`),
              like(notes.content, `%${search}%`),
            ),
          )
          .orderBy(desc(notes.updatedAt))
      : await this.db
          .select()
          .from(notes)
          .orderBy(desc(notes.updatedAt));

    return rows.map(mapNote);
  }

  async findById(id: number): Promise<Note | null> {
    const [row] = await this.db
      .select()
      .from(notes)
      .where(eq(notes.id, id))
      .limit(1);

    return row ? mapNote(row) : null;
  }

  async create(input: CreateNoteInput): Promise<Note> {
    const [row] = await this.db
      .insert(notes)
      .values({
        title: input.title ?? "",
        content: input.content ?? "",
      })
      .returning();

    return mapNote(row);
  }

  async update(id: number, input: UpdateNoteInput): Promise<Note | null> {
    const [row] = await this.db
      .update(notes)
      .set({
        ...(input.title !== undefined ? { title: input.title } : {}),
        ...(input.content !== undefined ? { content: input.content } : {}),
        updatedAt: new Date().toISOString(),
      })
      .where(eq(notes.id, id))
      .returning();

    return row ? mapNote(row) : null;
  }

  async delete(id: number): Promise<boolean> {
    const result = await this.db.delete(notes).where(eq(notes.id, id));
    return result.changes > 0;
  }
}

function mapNote(row: typeof notes.$inferSelect): Note {
  return {
    id: row.id,
    title: row.title,
    content: row.content,
    createdAt: row.createdAt,
    updatedAt: row.updatedAt,
  };
}
